def esc(s):
    s = s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
    s = s.replace('\\', '\\\\').replace("'", "\\'").replace('"', '\\"')
    if s.startswith('@') or s.startswith('?'): s = '\\' + s
    return s
for i, d in enumerate(['values', 'values-fr', 'values-de', 'values-es']):
    os.makedirs(os.path.join(RES, d), exist_ok=True)
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<!-- Genere : une seule table pour les quatre langues, comme les _locales de l\'extension. -->', '<resources>']
    for k, v in S.items():
        extra = ' translatable="false"' if k == 'app_name' and i == 0 else ''
        if k == 'app_name' and i > 0: continue
        fmt = ' formatted="false"' if ('%' in v[i] and '$' not in v[i]) else ''
        out.append(f'    <string name="{k}"{extra}{fmt}>{esc(v[i])}</string>')
    for k, v in P.items():
        one, other = v[i]
        out.append(f'    <plurals name="{k}">')
        out.append(f'        <item quantity="one">{esc(one)}</item>')
        out.append(f'        <item quantity="other">{esc(other)}</item>')
        if d == 'values-fr' or d == 'values-es':
            out.append(f'        <item quantity="many">{esc(other)}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    open(os.path.join(RES, d, 'strings.xml'), 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print(len(S), 'chaines,', len(P), 'pluriels')
